import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    @Test
    public void testGetTextBuffer_SharedInputBuffer() {
        char[] shared = {'a', 'b', 'c'};
        // resetWithShared sets _inputStart to a non-negative value
        textBuffer.resetWithShared(shared, 0, 3);

        char[] result = textBuffer.getTextBuffer();

        assertSame("Should return the shared input buffer when _inputStart >= 0", shared, result);
    }








}

package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }



    @Test
    public void testGetTextBuffer_ResultArray() {
        // To reach the _resultArray != null branch, we need to bypass _inputStart < 0
        // We can use resetWithCopy which populates the internal buffer/segments
        // and then trigger a state where _resultArray is set.
        // However, in Jackson's TextBuffer, _resultArray is typically set via resetWithString.

        // Let's use resetWithString to test the _resultString != null branch first
        textBuffer.resetWithString("test");
        // After resetWithString, _resultString is not null. 
        // The first call to getTextBuffer() will trigger the (_resultArray = _resultString.toCharArray()) branch.

        char[] expected = "test".toCharArray();
        char[] result1 = textBuffer.getTextBuffer();

        assertArrayEquals(expected, result1);

        // The second call should hit the if (_resultArray != null) branch
        char[] result2 = textBuffer.getTextBuffer();
        assertSame("Should return the same cached _resultArray on second call", result1, result2);
    }






}

