package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }







    @Test
    public void testGetTextBuffer_CurrentSegment() {
        // To reach !hasSegments && true branch:
        // 1. _inputStart < 0
        // 2. _resultArray == null
        // 3. _resultString == null
        // 4. _hasSegments is false

        // fresh TextBuffer has _hasSegments = false
        char[] result = textBuffer.getTextBuffer();

        // It should return the current segment (the internal buffer)
        assertNotNull(result);
        // Since it's a fresh buffer, it's the internal segment
        assertSame(textBuffer.getCurrentSegment(), result);
    }


}

package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }









    @Test
    public void testGetTextBuffer_ContentsAsArray() {
        // To reach contentsAsArray() branch:
        // 1. _inputStart < 0
        // 2. _resultArray == null
        // 3. _resultString == null
        // 4. _hasSegments is true

        // We force _hasSegments to be true by appending data that exceeds the first segment
        // or by finishing a segment.
        textBuffer.append('a');
        textBuffer.finishCurrentSegment(); 
        // finishCurrentSegment sets _hasSegments = true

        char[] result = textBuffer.getTextBuffer();

        // Should call contentsAsArray() which aggregates segments
        assertNotNull(result);
        assertEquals(1, result.length);
        assertEquals('a', result[0]);
    }
}
